from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN
import math

getcontext().prec = 80

_Q2 = Decimal("0.01")


class _ParamError(Exception):
    pass


def _d(v, default="0"):
    if v is None:
        return Decimal(default)
    s = str(v).strip()
    if s == "":
        return Decimal(default)
    try:
        return Decimal(s)
    except Exception:
        return Decimal(default)


def _r2(x):
    return Decimal(x).quantize(_Q2, rounding=ROUND_HALF_UP)


def _days(s):
    t = str(s).strip()[:10]
    if "-" in t:
        p = t.split("-")
        y, m, d = int(p[0]), int(p[1]), int(p[2])
    elif "/" in t:
        p = t.split("/")
        if len(p[0]) == 4:
            y, m, d = int(p[0]), int(p[1]), int(p[2])
        else:
            d, m, y = int(p[0]), int(p[1]), int(p[2])
    else:
        t = str(s).strip()[:8]
        y, m, d = int(t[0:4]), int(t[4:6]), int(t[6:8])
    y2 = y - 1 if m <= 2 else y
    era = y2 // 400
    yoe = y2 - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe


def _parse_params(s):
    res = {}
    if s is None:
        return res
    t = str(s)
    for ch in "{}[]\"'":
        t = t.replace(ch, "")
    t = t.replace("\n", ",").replace(";", ",").replace("|", ",")
    for part in t.split(","):
        part = part.strip()
        if not part:
            continue
        if "=" in part:
            k, v = part.split("=", 1)
        elif ":" in part:
            k, v = part.split(":", 1)
        else:
            continue
        k = k.strip().upper()
        v = v.strip()
        try:
            res[k] = Decimal(v)
        except Exception:
            pass
    return res


def _bool(v):
    return str(v).strip().upper() in ("TRUE", "1", "S", "SI", "Y", "YES", "T")


def run(inp: dict) -> dict:
    out = {
        "status": "",
        "reason_code": "",
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "observations": "",
        "claim_new_status": "",
        "error_code": "",
    }
    params = _parse_params(inp.get("params"))

    def P(name):
        if name not in params:
            raise _ParamError(name)
        return params[name]

    if str(inp.get("claim_status", "")).strip() != "REGISTRADO":
        out["error_code"] = "ORA-20001"
        return out

    obs = []

    def finish(status, reason, base, ded, cub, ret, neto):
        out["status"] = status
        out["reason_code"] = reason
        out["base_amount"] = str(base.quantize(_Q2))
        out["deductible_amount"] = str(ded.quantize(_Q2))
        out["covered_amount"] = str(cub.quantize(_Q2))
        out["withholding_amount"] = str(ret.quantize(_Q2))
        out["net_amount"] = str(neto.quantize(_Q2))
        out["observations"] = ";".join(obs)
        out["claim_new_status"] = {
            "APROBADA": "LIQUIDADO",
            "RECHAZADA": "RECHAZADO",
            "PENDIENTE_APROBACION": "PENDIENTE_REVISION",
        }[status]
        return out

    Z = Decimal("0.00")

    def reject(reason):
        return finish("RECHAZADA", reason, Z, Z, Z, Z, Z)

    try:
        reclamado = _r2(_d(inp.get("claimed_amount")))
        occ = _days(inp["occurrence_date"])
        rep = _days(inp["report_date"])
        ini = _days(inp["policy_start_date"])
        fin = _days(inp["policy_end_date"])
        suma = _r2(_d(inp.get("sum_insured")))
        ded_tipo = str(inp.get("deductible_type", "")).strip()
        ded_valor = _r2(_d(inp.get("deductible_value")))
        prima = _r2(_d(inp.get("pending_premium")))
        categoria = str(inp.get("customer_category", "")).strip()
        ramo = str(inp.get("policy_branch", "")).strip()
        limite = _r2(_d(inp.get("coverage_limit")))
        pct_cob = _r2(_d(inp.get("coverage_percentage")))
        carencia = _d(inp.get("waiting_days"))
        prev = _d(inp.get("prior_liquidated_claims_365d"))
        total_ind = _r2(_d(inp.get("total_indemnified")))

        if str(inp.get("policy_status", "")).strip() != "VIGENTE":
            return reject("POLIZA_NO_VIGENTE")

        if occ < ini or occ > fin:
            return reject("FUERA_DE_VIGENCIA")

        dias_den = rep - occ
        if ramo == "VIDA":
            max_den = P("DIAS_MAX_DENUNCIA_VIDA")
        else:
            max_den = P("DIAS_MAX_DENUNCIA")
        if dias_den > max_den:
            return reject("DENUNCIA_EXTEMPORANEA")

        if not _bool(inp.get("coverage_found")):
            return reject("COBERTURA_NO_CONTRATADA")

        dias_ini = occ - ini
        if dias_ini < carencia:
            return reject("EN_PERIODO_CARENCIA")

        if prima > 0:
            tol = P("TOLERANCIA_MORA_VIP")
            if categoria == "VIP" and prima <= tol:
                obs.append("TOLERANCIA_MORA_VIP")
            else:
                return reject("PRIMA_EN_MORA")

        # 2.a
        if reclamado > limite:
            base = limite
            obs.append("LIMITE_COBERTURA")
        else:
            base = reclamado

        # 2.b
        if ded_tipo == "FIJO":
            ded = ded_valor
        else:
            ded_min = P("DEDUCIBLE_MINIMO")
            ded = _r2(base * ded_valor / 100)
            if ded < ded_min:
                ded = _r2(ded_min)
                obs.append("DEDUCIBLE_MINIMO")
        if categoria == "VIP" and ded > 0:
            pdv = P("PCT_DESCUENTO_DED_VIP")
            ded = _r2(ded * (100 - pdv) / 100)
            obs.append("DESCUENTO_VIP")

        # 2.c
        cub = _r2((base - ded) * pct_cob / 100)
        if cub <= 0:
            return reject_keep(finish_rej=finish, reason="BAJO_DEDUCIBLE")

        # 2.d
        if prev >= P("MAX_SINIESTROS_ANUAL"):
            cub = _r2(cub * (100 - P("PCT_PENALIZACION_SINIEST")) / 100)
            obs.append("PENALIZACION_SINIESTRALIDAD")

        # 2.e
        remanente = suma - total_ind
        if remanente <= 0:
            return reject_keep(finish_rej=finish, reason="SUMA_ASEGURADA_AGOTADA")
        if cub > remanente:
            cub = remanente
            obs.append("TOPE_SUMA_ASEGURADA")

        # 2.f
        if ramo != "VIDA" and cub > P("UMBRAL_RETENCION"):
            ret = _r2(cub * P("TASA_RETENCION") / 100)
            obs.append("RETENCION_APLICADA")
        else:
            ret = Z
        neto = cub - ret

        # 3
        umbral = _r2(limite * P("PCT_ALERTA_FRAUDE") / 100)
        if dias_ini <= P("DIAS_ALERTA_FRAUDE") and reclamado >= umbral:
            est, mot = "PENDIENTE_APROBACION", "SOSPECHA_FRAUDE"
        elif neto > P("TOPE_AUTO_APROBACION"):
            est, mot = "PENDIENTE_APROBACION", "SUPERA_TOPE_AUTOMATICO"
        else:
            est, mot = "APROBADA", "LIQUIDACION_AUTOMATICA"
        return finish(est, mot, base, ded, cub, ret, neto)
    except _ParamError:
        res = {
            "status": "",
            "reason_code": "",
            "base_amount": "0.00",
            "deductible_amount": "0.00",
            "covered_amount": "0.00",
            "withholding_amount": "0.00",
            "net_amount": "0.00",
            "observations": "",
            "claim_new_status": "",
            "error_code": "ORA-20010",
        }
        return res


def reject_keep(finish_rej, reason):
    # Rechazo con importes en cero conservando las observaciones acumuladas.
    return finish_rej("RECHAZADA", reason, Decimal("0"), Decimal("0"), Decimal("0"), Decimal("0"), Decimal("0"))
